// Its cells sit in merged ranges, so each value is a few columns from the next.
const row = (c: Record<number, string>) => Array.from({ length: 25 }, (_, i) => c[i] ?? '');

const purchase = (date: string, description: string, amount: string, mark = '') =>
	row({
		0: 'Domestic',
		4: 'A N OTHER       [CKYC ID]',
		9: date,
		12: description,
		20: amount,
		23: mark,
	});

const card = [
	row({ 0: 'Name', 4: 'A N OTHER' }),
	row({ 0: 'Address', 4: '1 EXAMPLE STREET', 13: 'Credit Card No.: 000000XXXXXX0000' }),
	row({ 0: 'Statement Date', 4: '14 Sep, 2026' }),
	row({ 0: 'Total Amount Due', 4: '1,409.00' }),
	[],
	row({ 0: 'Account Summary' }),
	row({ 0: 'Opening Bal', 5: 'Payment / Credit', 10: 'Purchases / Debits', 20: 'Total Dues' }),
	row({ 0: '7,073.00', 5: '7,074.00', 10: '1,410.00', 20: '1,409.00' }),
	[],
	row({
		0: 'Transaction type',
		4: 'Primary / Addon Customer ',
		9: 'Date & Time',
		12: 'Description',
		18: 'REWARDS',
		20: 'AMT',
		23: 'Debit / Credit',
	}),
	purchase('15/08/2026 / 18:41', 'UPI-CITY CAFE  ', '195.00'),
	purchase('15/08/2026 / 19:02', 'CREDIT CARD PAYMENT Net Banking', '7,073.00', 'Cr'),
	purchase('18/08/2026 / 16:01', 'UPI-CORNER PHARMACY  ', '1,215.00'),
	purchase('18/08/2026 / 16:31', 'UPI-CORNER PHARMACY  ', '1.00', 'Cr'),
	[],
	row({ 0: 'Reward Points Summary' }),
	row({ 0: 'Opening Balance', 7: 'Disbursed', 14: 'Reward Points' }),
	row({ 0: '5,000', 7: '0', 14: '5,024' }),
	[],
	row({ 0: 'Registered Office Address: HDFC Bank Cards Divison, Chennai – 600058' }),
];

const write = (name: string, rows: (string | number)[][]) => {
	const book = XLSX.utils.book_new();
	XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet(rows));
	writeFileSync(join(out, name), XLSX.write(book, { type: 'buffer', bookType: 'biff8' }));
};

write('hdfc-savings.xls', savings);
write('hdfc-card.xls', card);
